import numpy as np
from scipy.optimize import minimize

def f(params):
    alpha, beta = params
    if alpha <= 0 or beta <= 0:
        return 1e9
    return -32 * (alpha * beta * (1 + alpha + beta)) / ((1 + alpha)**2 * (1 + beta)**2)

# Test several starting points
results = []
for a_start in [0.1, 1.0, 2.0, 5.0, 10.0]:
    for b_start in [0.1, 1.0, 2.0, 5.0, 10.0]:
        res = minimize(f, [a_start, b_start], bounds=((0.001, None), (0.001, None)))
        results.append(-res.fun)

print(f"Max values found: {results}")
